import React, {useEffect, useId, useRef} from 'react';
import './dialog.css';
export type DetailItem = {id: string; title: string; summary: string; owner: string; updated: string};
export function ItemDialog({open, items, selectedId, onSelect, onClose, onConfirm}: {open: boolean; items: DetailItem[]; selectedId: string | null; onSelect: (id: string) => void; onClose: () => void; onConfirm: (id: string) => void}) {
 const ref = useRef<HTMLDialogElement>(null); const id = useId(); const item = items.find(value => value.id === selectedId);
 useEffect(() => {const dialog = ref.current!; if (!open) {if (dialog.open) dialog.close(); return;} const previous = document.activeElement as HTMLElement | null; if (!dialog.open) dialog.showModal(); return () => {if (dialog.open) dialog.close(); if (previous?.isConnected) previous.focus();};}, [open]);
 return <dialog className="item-dialog" ref={ref} aria-labelledby={`${id}-title`} aria-describedby={`${id}-summary`} onCancel={event => {event.preventDefault(); onClose();}}><div className="dialog-scroll"><header><h1 id={`${id}-title`}>Choose an item</h1><p id={`${id}-summary`}>Select an item to review its details, then confirm your selection.</p></header><div className="master-detail"><fieldset className="item-master"><legend>Available items</legend>{items.length === 0 && <p>No items available.</p>}{items.map(value => <label key={value.id}><input type="radio" name={`${id}-selection`} checked={selectedId === value.id} onChange={() => onSelect(value.id)}/>{value.title}</label>)}</fieldset><section className="item-detail" aria-label="Selected item details">{item ? <><h2>{item.title}</h2><p>{item.summary}</p><dl><dt>Owner</dt><dd>{item.owner}</dd><dt>Last updated</dt><dd>{item.updated}</dd></dl></> : <p>Select an item to see its details.</p>}</section></div><footer><button onClick={onClose}>Cancel</button><button className="primary" disabled={!item} onClick={() => item && onConfirm(item.id)}>Use selected item</button></footer></div></dialog>;
}
